wrapped = functools.cache(my_async_fn)

dep = Dependant(call=wrapped)
print(f"is_coroutine_callable (before fix): {dep.is_coroutine_callable}")

# Simulate the fix
def fixed_is_coroutine_callable(self):
    if self.call is None:
        return False
    call = inspect.unwrap(self.call)
    if inspect.isroutine(call):
        # Use the same logic as in Dependant.is_coroutine_callable
        # In Dependant, it uses iscoroutinefunction which is imported from asyncio or inspect
        return asyncio.iscoroutinefunction(call)
    if inspect.isclass(call):
        return False
    dunder_call = getattr(call, "__call__", None)
    return asyncio.iscoroutinefunction(dunder_call)

# Monkeypatch for testing
# Since it's a cached_property, we can't easily monkeypatch the class and expect it to work on existing instances.
# But we can just test the logic.

class FixedDependant(Dependant):
    @property
    def is_coroutine_callable(self) -> bool:
        if self.call is None:
            return False
        call = inspect.unwrap(self.call)
        if inspect.isroutine(call):
            return asyncio.iscoroutinefunction(call)
        if inspect.isclass(call):
            return False
        dunder_call = getattr(call, "__call__", None)
        return asyncio.iscoroutinefunction(dunder_call)

dep_fixed = FixedDependant(call=wrapped)
print(f"is_coroutine_callable (after fix): {dep_fixed.is_coroutine_callable}")

